// Temporary standalone verifier. Replicates the test cases that are gated
// behind EXERCISM_RUN_ALL_TESTS in binary_search_tree_test.cpp, but with a
// plain main() so it can be built/run without that macro. Not part of the
// solution; deleted after verification.
#include "binary_search_tree.h"
#include <cstdint>
#include <iostream>
#include <string>
#include <vector>

template <typename T>
using tree_ptr = std::unique_ptr<binary_search_tree::binary_tree<T>>;

static int failures = 0;

#define CHECK(cond)                                                        \
    do {                                                                   \
        if (!(cond)) {                                                     \
            ++failures;                                                    \
            std::cout << "FAIL: " << #cond << " (line " << __LINE__ << ")" \
                      << std::endl;                                        \
        }                                                                  \
    } while (0)

template <typename T>
static void test_leaf(const tree_ptr<T>& tree, const T& data, bool has_left, bool has_right)
{
    CHECK(data == tree->data());
    CHECK(static_cast<bool>(tree->left()) == has_left);
    CHECK(static_cast<bool>(tree->right()) == has_right);
}

template <typename T>
static tree_ptr<T> make_tree(const std::vector<T>& data)
{
    if (data.empty())
        return tree_ptr<T>(nullptr);
    auto data_iter = data.begin();
    auto tree = tree_ptr<T>(new binary_search_tree::binary_tree<T>(*data_iter));
    ++data_iter;
    for (; data_iter != data.end(); ++data_iter) {
        tree->insert(*data_iter);
    }
    return tree;
}

template <typename T>
static void test_sort(const tree_ptr<T>& tree, const std::vector<T>& expected)
{
    std::vector<T> actual;
    for (auto& x : *tree) {
        actual.push_back(x);
    }
    CHECK(expected == actual);
}

int main()
{
    {
        auto tested = make_tree<uint32_t>({4, 2});
        test_leaf<uint32_t>(tested, 4, true, false);
        test_leaf<uint32_t>(tested->left(), 2, false, false);
    }
    {
        auto tested = make_tree<uint32_t>({4, 4});
        test_leaf<uint32_t>(tested, 4, true, false);
        test_leaf<uint32_t>(tested->left(), 4, false, false);
    }
    {
        auto tested = make_tree<uint32_t>({4, 5});
        test_leaf<uint32_t>(tested, 4, false, true);
        test_leaf<uint32_t>(tested->right(), 5, false, false);
    }
    {
        std::cout << "[complex_tree] start" << std::endl;
        auto tested = make_tree<uint32_t>({4, 2, 6, 1, 3, 5, 7});
        std::cout << "[complex_tree] root" << std::endl;
        test_leaf<uint32_t>(tested, 4, true, true);
        std::cout << "[complex_tree] left(2)" << std::endl;
        test_leaf<uint32_t>(tested->left(), 2, true, true);
        std::cout << "[complex_tree] right(6)" << std::endl;
        test_leaf<uint32_t>(tested->right(), 6, true, true);
        std::cout << "[complex_tree] left->left(1)" << std::endl;
        test_leaf<uint32_t>(tested->left()->left(), 1, false, false);
        std::cout << "[complex_tree] left->right(3)" << std::endl;
        test_leaf<uint32_t>(tested->left()->right(), 3, false, false);
        std::cout << "[complex_tree] right->left(5)" << std::endl;
        test_leaf<uint32_t>(tested->right()->left(), 5, false, false);
        std::cout << "[complex_tree] right->right(7)" << std::endl;
        test_leaf<uint32_t>(tested->right()->right(), 7, false, false);
        std::cout << "[complex_tree] done" << std::endl;
    }

    test_sort(make_tree<uint32_t>({2}), {2});
    test_sort(make_tree<uint32_t>({2, 1}), {1, 2});
    test_sort(make_tree<uint32_t>({2, 2}), {2, 2});
    test_sort(make_tree<uint32_t>({2, 3}), {2, 3});
    test_sort(make_tree<uint32_t>({2, 1, 3, 6, 7, 5}), {1, 2, 3, 5, 6, 7});

    {
        auto tested = make_tree<std::string>({"delicious", "ballon", "flag", "apple", "cat", "elispsis", "grains"});
        test_leaf<std::string>(tested, "delicious", true, true);
        test_leaf<std::string>(tested->left(), "ballon", true, true);
        test_leaf<std::string>(tested->right(), "flag", true, true);
        test_leaf<std::string>(tested->left()->left(), "apple", false, false);
        test_leaf<std::string>(tested->left()->right(), "cat", false, false);
        test_leaf<std::string>(tested->right()->left(), "elispsis", false, false);
        test_leaf<std::string>(tested->right()->right(), "grains", false, false);
    }
    test_sort(make_tree<std::string>({"A", "few", "random", "strings", "that", "should", "be", "sorted"}),
              {"A", "be", "few", "random", "should", "sorted", "strings", "that"});

    if (failures == 0) {
        std::cout << "ALL GATED TEST CASES PASSED" << std::endl;
        return 0;
    }
    std::cout << failures << " CHECK(S) FAILED" << std::endl;
    return 1;
}

#ifndef BINARY_SEARCH_TREE_H
#define BINARY_SEARCH_TREE_H

#include <cstddef>
#include <iterator>
#include <memory>
#include <stack>

namespace binary_search_tree {

template <typename T>
class binary_tree {
public:
    explicit binary_tree(const T& data) : data_{data} {}

    const T& data() const { return data_; }

    // Return an owning copy of the left/right subtree. The real tree is left
    // untouched, so callers may destroy the returned pointer freely and the
    // tree remains valid for further access.
    std::unique_ptr<binary_tree> left() const { return left_ ? left_->clone() : nullptr; }
    std::unique_ptr<binary_tree> right() const { return right_ ? right_->clone() : nullptr; }

    void insert(const T& data) {
        if (data <= data_) {
            if (left_ == nullptr) {
                left_ = std::make_unique<binary_tree>(data);
            } else {
                left_->insert(data);
            }
        } else {
            if (right_ == nullptr) {
                right_ = std::make_unique<binary_tree>(data);
            } else {
                right_->insert(data);
            }
        }
    }

    // Deep copy of this subtree.
    std::unique_ptr<binary_tree> clone() const {
        auto copy = std::make_unique<binary_tree>(data_);
        if (left_) copy->left_ = left_->clone();
        if (right_) copy->right_ = right_->clone();
        return copy;
    }

    class iterator {
    public:
        using difference_type = std::ptrdiff_t;
        using value_type = T;
        using pointer = const T*;
        using reference = const T&;
        using iterator_category = std::forward_iterator_tag;

        iterator() = default;

        explicit iterator(const binary_tree* tree) {
            while (tree != nullptr) {
                stack_.push(tree);
                tree = tree->left_.get();
            }
            if (!stack_.empty()) {
                tree_ = stack_.top();
                stack_.pop();
            }
        }

        reference operator*() const { return tree_->data(); }
        pointer operator->() const { return &tree_->data(); }

        iterator& operator++() {
            if (tree_->right_ != nullptr) {
                tree_ = tree_->right_.get();
                while (tree_ != nullptr) {
                    stack_.push(tree_);
                    tree_ = tree_->left_.get();
                }
                if (!stack_.empty()) {
                    tree_ = stack_.top();
                    stack_.pop();
                }
            } else {
                tree_ = stack_.empty() ? nullptr : stack_.top();
                if (!stack_.empty()) {
                    stack_.pop();
                }
            }
            return *this;
        }

        bool operator==(const iterator& other) const { return tree_ == other.tree_; }
        bool operator!=(const iterator& other) const { return !(*this == other); }

    private:
        const binary_tree* tree_ = nullptr;
        std::stack<const binary_tree*> stack_;
    };

    iterator begin() { return iterator(this); }
    iterator end() { return iterator(); }

private:
    T data_;
    std::unique_ptr<binary_tree> left_;
    std::unique_ptr<binary_tree> right_;
};

}  // namespace binary_search_tree

#endif  // BINARY_SEARCH_TREE_H

