40:     // Deep copy of this subtree.
41:     std::unique_ptr<binary_tree> clone() const {
42:         auto copy = std::make_unique<binary_tree>(data_);
43:         if (left_) copy->left_ = left_->clone();
44:         if (right_) copy->right_ = right_->clone();
45:         return copy;
46:     }
47: 
48:     class iterator {
49:     public:
50:         using difference_type = std::ptrdiff_t;
51:         using value_type = T;
52:         using pointer = const T*;
53:         using reference = const T&;
54:         using iterator_category = std::forward_iterator_tag;
55: 
56:         iterator() = default;
57: 
58:         explicit iterator(const binary_tree* tree) {
59:             while (tree != nullptr) {
60:                 stack_.push(tree);
61:                 tree = tree->left_.get();
62:             }
63:             if (!stack_.empty()) {
64:                 tree_ = stack_.top();
65:                 stack_.pop();
66:             }
67:         }
68: 
69:         reference operator*() const { return tree_->data(); }
70:         pointer operator->() const { return &tree_->data(); }
71: 
72:         iterator& operator++() {
73:             if (tree_->right_ != nullptr) {
74:                 tree_ = tree_->right_.get();
75:                 while (tree_ != nullptr) {
76:                     stack_.push(tree_);
77:                     tree_ = tree_->left_.get();
78:                 }
79:                 if (!stack_.empty()) {
80:                     tree_ = stack_.top();
81:                     stack_.pop();
82:                 }
83:             } else {
84:                 tree_ = stack_.empty() ? nullptr : stack_.top();
85:                 if (!stack_.empty()) {
86:                     stack_.pop();
87:                 }
88:             }
89:             return *this;
90:         }
91: 
92:         bool operator==(const iterator& other) const { return tree_ == other.tree_; }
93:         bool operator!=(const iterator& other) const { return !(*this == other); }
94: 
95:     private:
96:         const binary_tree* tree_ = nullptr;
97:         std::stack<const binary_tree*> stack_;
98:     };
99: 
100:     iterator begin() const { return iterator(this); }
101:     iterator end() const { return iterator(); }
102: 
103: private:
104:     T data_;
105:     std::unique_ptr<binary_tree> left_;
106:     std::unique_ptr<binary_tree> right_;
107: };
